import { create } from 'zustand';
import { log } from './logger';

/**
 * Service worker registration with a "new version available" prompt (registerType: 'prompt').
 * `virtual:pwa-register` is generated by vite-plugin-pwa; in dev and in tests the SW is not registered.
 */
interface PwaState {
  worker: 'unsupported' | 'none' | 'installing' | 'active' | 'error';
  updateReady: boolean;
  offlineReady: boolean;
  /** Applies the waiting worker and reloads. */
  applyUpdate: (() => Promise<void>) | null;
}

export const usePwaStore = create<PwaState>(() => ({
  worker: 'serviceWorker' in navigator ? 'none' : 'unsupported',
  updateReady: false,
  offlineReady: false,
  applyUpdate: null,
}));

export function usePwaStatus() {
  return usePwaStore();
}

export async function registerPwa(): Promise<void> {
  if (!('serviceWorker' in navigator) || import.meta.env.DEV) return;
  try {
    const { registerSW } = await import('virtual:pwa-register');
    const update = registerSW({
      immediate: true,
      onNeedRefresh: () => usePwaStore.setState({ updateReady: true }),
      onOfflineReady: () => usePwaStore.setState({ offlineReady: true, worker: 'active' }),
      onRegisteredSW: (_url, reg) => {
        usePwaStore.setState({ worker: reg?.active ? 'active' : 'installing' });
        // iOS rarely checks for updates on its own: look when the app comes back to the foreground.
        document.addEventListener('visibilitychange', () => {
          if (!document.hidden) void reg?.update().catch(() => undefined);
        });
      },
      onRegisterError: (e) => {
        log.warn('pwa', 'service worker registration failed', e);
        usePwaStore.setState({ worker: 'error' });
      },
    });
    usePwaStore.setState({ applyUpdate: () => update(true) });
  } catch (e) {
    log.warn('pwa', 'could not load the service worker helper', e);
  }
}
